```typescript
/**
 * ESI.ts Example: Streaming Pagination
 *
 * Demonstrates streaming through large paginated datasets without
 * loading everything into memory at once. Uses market orders in
 * The Forge (Jita's region) as the example since it has the most pages.
 *
 * Usage: npm run example:streaming
 */
import { EsiClient, PageResult, MarketOrder } from '../src';

const FORGE_REGION_ID = 10000002;

async function streamAllOrders() {
  const client = new EsiClient();
  try {
    console.log('Streaming Market Orders (The Forge)\n');
    let totalOrders = 0;
    let buyOrders = 0;
    let sellOrders = 0;

    for await (const page of client.market.streamMarketOrders(FORGE_REGION_ID)) {
      totalOrders += page.data.length;
      buyOrders += page.data.filter(o => o.is_buy_order).length;
      sellOrders += page.data.filter(o => !o.is_buy_order).length;

      console.log(`  Page ${page.page}/${page.totalPages}: ${page.data.length} orders (running total: ${totalOrders})`);
    }

    console.log(`\nDone! ${totalOrders} total orders (${buyOrders} buy, ${sellOrders} sell)`);
  } finally {
    client.shutdown();
  }
}

async function streamWithEarlyStop() {
  const client = new EsiClient();
  try {
    console.log('\nStreaming with Early Stop (first 3 pages only)\n');
    let count = 0;

    for await (const page of client.market.streamMarketOrders(FORGE_REGION_ID)) {
      count += page.data.length;
      console.log(`  Page ${page.page}/${page.totalPages}: ${page.data.length} orders`);
      if (page.page >= 3) {
        console.log('  (stopping early)');
        break;
      }
    }
    console.log(`  Processed ${count} orders from 3 pages`);
  } finally {
    client.shutdown();
  }
}

async function main() {
  await streamAllOrders();
  await streamWithEarlyStop();
}

main();
```

